// Foundry VTT Macro: Copy Active Effect (universal) — V2 Application API
// Копирует Active Effect из компендиума-склада "dedrel.active_effects" (или с актёра
// выделенного токена / с его предметов) на цель: актёров выделенных токенов ИЛИ открытый лист предмета
// (например, «повесить свет» на меч/фонарь/факел). Не требует ручной пересборки эффекта.
(async () => {
    const PACK_KEY = "dedrel.active_effects";

    // --- Источники: эффекты из компендиума-склада ---
    const sources = [];
    const pack = game.packs.get(PACK_KEY);
    if (pack) {
        const docs = await pack.getDocuments();
        for (const doc of docs) {
            for (const eff of doc.effects) {
                sources.push({ value: `carrier:${doc.id}:${eff.id}`, label: `${doc.name} — ${eff.name}`, effect: eff });
            }
        }
    }
    // Дополнительно: эффекты с актёра единственного выделенного токена —
    // как созданные на самом актёре (actor.effects), так и лежащие на его
    // предметах (item.effects), напр. пакет «Бестелесный» на Item'е creature_type.
    // Транзитные предметные эффекты в actor.effects не попадают, поэтому items перебираем явно.
    const selTokens = canvas.tokens?.controlled ?? [];
    if (selTokens.length === 1 && selTokens[0].actor) {
        const actor = selTokens[0].actor;
        for (const eff of actor.effects) {
            sources.push({ value: `sel:${eff.id}`, label: `${selTokens[0].name} — ${eff.name}`, effect: eff });
        }
        for (const item of actor.items) {
            for (const eff of item.effects) {
                sources.push({ value: `selitem:${item.id}:${eff.id}`, label: `${selTokens[0].name} · ${item.name} — ${eff.name}`, effect: eff });
            }
        }
    }
    if (sources.length === 0) {
        return ui.notifications.warn("Нет источников эффектов. Заполните компендиум «Active Effects» (seed-макрос) или выделите токен с эффектами.");
    }

    // --- Цели: выделенные токены и/или открытые листы предметов ---
    const targets = [];
    if (selTokens.length > 0) targets.push({ value: "tokens", label: `Актёры выделенных токенов (${selTokens.length})` });

    const openApps = [
        ...(foundry.applications?.instances ? [...foundry.applications.instances.values()] : []),
        ...(ui.windows ? Object.values(ui.windows) : [])
    ];
    const seenItems = new Set();
    for (const app of openApps) {
        const doc = app?.document;
        if (!app?.rendered || doc?.documentName !== "Item" || seenItems.has(doc.id)) continue;
        seenItems.add(doc.id);
        targets.push({ value: `item:${doc.uuid}`, label: `Предмет: ${doc.name}` });
    }
    if (targets.length === 0) {
        return ui.notifications.warn("Нет целей: выделите токены и/или откройте лист предмета, куда копировать.");
    }

    const srcOptions = sources.map(s => `<option value="${s.value}">${foundry.utils.escapeHTML(s.label)}</option>`).join("");
    const tgtOptions = targets.map(t => `<option value="${t.value}">${foundry.utils.escapeHTML(t.label)}</option>`).join("");

    const choice = await foundry.applications.api.DialogV2.wait({
        window: { title: "Копирование активного эффекта" },
        content: `
            <div class="form-group" style="margin-bottom:10px;">
                <label style="font-weight:bold; display:block; margin-bottom:4px;">Источник (эффект):</label>
                <select name="src" style="width:100%; padding:4px;">${srcOptions}</select>
            </div>
            <div class="form-group" style="margin-bottom:10px;">
                <label style="font-weight:bold; display:block; margin-bottom:4px;">Куда копировать:</label>
                <select name="tgt" style="width:100%; padding:4px;">${tgtOptions}</select>
            </div>
        `,
        buttons: [
            {
                action: "copy",
                icon: "fa-solid fa-copy",
                label: "Копировать",
                default: true,
                callback: (event, button, dialog) => ({
                    src: dialog.element.querySelector("[name=src]").value,
                    tgt: dialog.element.querySelector("[name=tgt]").value
                })
            },
            { action: "cancel", icon: "fa-solid fa-times", label: "Отмена" }
        ]
    });
    if (!choice || choice === "cancel") return;

    const srcEntry = sources.find(s => s.value === choice.src);
    if (!srcEntry) return;
    // Свежие данные эффекта без исходного _id (чтобы не было коллизии при создании)
    const baseData = srcEntry.effect.toObject();
    delete baseData._id;

    if (choice.tgt === "tokens") {
        let count = 0;
        for (const token of selTokens) {
            if (!token.actor) continue;
            const data = foundry.utils.deepClone(baseData);
            data.origin = token.actor.uuid;
            await token.actor.createEmbeddedDocuments("ActiveEffect", [data]);
            count++;
        }
        return ui.notifications.info(`Эффект скопирован на актёров: ${count}.`);
    }

    if (choice.tgt.startsWith("item:")) {
        const item = await fromUuid(choice.tgt.slice(5));
        if (!item) return ui.notifications.error("Целевой предмет не найден (лист закрыт?).");
        const data = foundry.utils.deepClone(baseData);
        data.origin = item.uuid;
        // На предмете эффект — накладываемый вручную шаблон (кнопка «Применить эффекты»).
        data.transfer = false;
        await item.createEmbeddedDocuments("ActiveEffect", [data]);
        return ui.notifications.info(`Эффект скопирован на предмет «${item.name}».`);
    }
})();
